<template><view class="page">
  <swiper class="announce" indicator-dots autoplay circular><swiper-item v-for="item in announcements" :key="item.title"><view class="ann"><image :src="item.image" mode="aspectFill"/><view class="ann-info"><text class="tag">{{item.tag}}</text><text class="ann-title">{{item.title}}</text><text class="ann-sub">{{item.sub}}</text></view></view></swiper-item></swiper>
  <view class="card overview"><view><text class="num orange">312</text><text class="label">累计卡路里 (kcal)</text></view><view class="divider"/><view><text class="num">4.50</text><text class="label">累计里程 (km)</text></view></view>
  <view class="section-title">勋章展馆</view><view class="card medal-hall" @tap="go('/pages/achievement/achievement')"><text class="intro">完赛线路即可铸造专属勋章 · 已收藏 1/3 枚</text><view class="medals"><view v-for="(r,i) in routes" :key="r.id"><image :class="{locked:i>0}" :src="r.medal" mode="aspectFit"/><text>{{r.spirit}}</text><text class="state">{{i===0?'已收藏':'未解锁'}}</text></view></view><view class="enter">进入勋章展馆，查看勋章价值 ›</view></view>
  <view class="section-title">推荐路跑线路</view><view class="route" v-for="r in routes" :key="r.id" @tap="go('/pages/route/route?id='+r.id)"><view class="route-head"><image :src="r.scene" mode="aspectFill"/><view class="mask"/><view class="route-top"><text>{{r.name}}</text><text class="spirit">{{r.spirit}}</text></view><text class="path">{{r.from}} 至 {{r.to}} · 全程 {{r.total}}km</text></view><view class="route-body"><text class="desc">{{r.desc}}</text><view class="progress"><view :style="{width:r.pct+'%',background:r.theme}"/></view><view class="foot"><text>已跑 {{r.distance}}km · 抵达 {{r.current}}</text><text class="orange">{{r.pct}}%</text></view></view></view>
  <view class="tip">选择一条线路，开始你的虚拟远征</view>
</view></template>
<script>import {routes,announcements} from '../../common/mock.js'; export default{data:()=>({routes,announcements}),methods:{go(url){uni.navigateTo({url})}}}</script>
